function InstallApp({language}:{language:"en"|"fr"}){const[deferred,setDeferred]=useState<InstallPromptEvent|null>(null);const[visible,setVisible]=useState(false);const[iosHelp,setIosHelp]=useState(false);const[mobile,setMobile]=useState(false);const en=language==="en";useEffect(()=>{const standalone=window.matchMedia("(display-mode: standalone)").matches||(navigator as Navigator&{standalone?:boolean}).standalone===true;if(standalone){setVisible(false);return}const isMobile=window.matchMedia("(max-width: 820px)").matches;const isIos=/iphone|ipad|ipod/i.test(navigator.userAgent);setMobile(isMobile);if("serviceWorker" in navigator){navigator.serviceWorker.register(`${process.env.NEXT_PUBLIC_BASE_PATH??""}/sw.js`,{scope:`${process.env.NEXT_PUBLIC_BASE_PATH??""}/`}).catch(()=>undefined)}const before=(event:Event)=>{event.preventDefault();setDeferred(event as InstallPromptEvent);setVisible(true)};const installed=()=>{setVisible(false);setDeferred(null)};window.addEventListener("beforeinstallprompt",before);window.addEventListener("appinstalled",installed);if(isIos&&isMobile)setVisible(true);return()=>{window.removeEventListener("beforeinstallprompt",before);window.removeEventListener("appinstalled",installed)}},[]);const install=async()=>{if(deferred){await deferred.prompt();const choice=await deferred.userChoice;if(choice.outcome==="accepted")setVisible(false);setDeferred(null)}else setIosHelp(true)};if(!visible)return null;return <aside className={mobile?"install-card mobile-install":"install-card desktop-install"}><button className="install-close" onClick={()=>setVisible(false)} aria-label={en?"Close":"Fermer"}><X/></button><span className="install-icon"><Image src={`${process.env.NEXT_PUBLIC_BASE_PATH??""}/nexus-app-icon.svg`} width={48} height={48} alt="KCS Nexus app"/></span><div><small>KCS NEXUS ACADEMY</small><b>{iosHelp?(en?"Install on your home screen":"Installer sur votre écran d’accueil"):(en?"Install the KCS app":"Installer l’application KCS")}</b><p>{iosHelp?(en?"Tap Share, then choose Add to Home Screen.":"Touchez Partager, puis Ajouter à l’écran d’accueil."):(en?"Faster access and essential content available offline.":"Accès rapide et contenus essentiels disponibles hors connexion.")}</p></div>{!iosHelp&&<button className="install-action" onClick={install}><Download/>{en?"Install":"Installer"}</button>}{iosHelp&&<span className="ios-steps"><Smartphone/> Share → Add to Home Screen</span>}</aside>}
