function LoginPage({language,setLanguage,onLogin}:{language:"en"|"fr";setLanguage:(value:"en"|"fr")=>void;onLogin:()=>void}){const[email,setEmail]=useState("");const[password,setPassword]=useState("");const[show,setShow]=useState(false);const[error,setError]=useState("");const en=language==="en";const submit=(e:React.FormEvent)=>{e.preventDefault();if(email.trim().toLowerCase()==="teacher.demo@kcs.cd"&&password==="KCS@Demo2026"){localStorage.setItem("kcs-demo-session","active");setError("");onLogin()}else setError(en?"Incorrect email or password. Use the demo credentials below.":"Adresse ou mot de passe incorrect. Utilisez les identifiants de démonstration ci-dessous.")};return <main className="login-page"><div className="login-orb one"/><div className="login-orb two"/><header><div className="login-brand"><span><Image src={`${process.env.NEXT_PUBLIC_BASE_PATH??""}/kcs.jpg`} width={46} height={46} alt="KCS logo" priority/></span><p><b>KCS <i>NEXUS</i></b><small>ACADEMY</small></p></div><button onClick={()=>{const next=en?"fr":"en";setLanguage(next);localStorage.setItem("kcs-language",next)}}><Languages/>{en?"FR":"EN"}</button></header><section className="login-shell"><div className="login-story"><small>{en?"KINSHASA CHRISTIAN SCHOOL":"KINSHASA CHRISTIAN SCHOOL"}</small><h1>{en?"Learning connected. Potential unlocked.":"L’apprentissage connecté. Le potentiel libéré."}</h1><p>{en?"One intelligent academic ecosystem to plan, teach, assess, understand, and help every learner grow.":"Un écosystème académique intelligent pour planifier, enseigner, évaluer, comprendre et faire progresser chaque élève."}</p><div className="login-values"><span><ShieldCheck/><b>{en?"Secure by design":"Sécurisé par conception"}</b></span><span><Sparkles/><b>{en?"Human-centered AI":"IA centrée sur l’humain"}</b></span><span><GraduationCap/><b>{en?"Built for KCS":"Conçu pour KCS"}</b></span></div><blockquote><span>“</span><p>{en?"Whatever you do, work at it with all your heart, as working for the Lord.":"Tout ce que vous faites, faites-le de tout votre cœur, comme pour le Seigneur."}<small>COLOSSIANS 3:23</small></p></blockquote></div><form className="login-card" onSubmit={submit} autoComplete="off"><div className="login-card-head"><span><LockKeyhole/></span><small>{en?"SECURE TEACHER PORTAL":"PORTAIL ENSEIGNANT SÉCURISÉ"}</small><h2>{en?"Welcome back":"Heureux de vous revoir"}</h2><p>{en?"Sign in to continue to KCS Nexus Academy.":"Connectez-vous pour accéder à KCS Nexus Academy."}</p></div><label>{en?"Email address":"Adresse e-mail"}<div><Mail/><input type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder={en?"Enter your school email":"Entrez votre adresse scolaire"} autoComplete="off" data-form-type="other" required/></div></label><label>{en?"Password":"Mot de passe"}<div><LockKeyhole/><input type={show?"text":"password"} value={password} onChange={e=>setPassword(e.target.value)} placeholder={en?"Enter your password":"Entrez votre mot de passe"} autoComplete="new-password" data-form-type="other" required/><button type="button" onClick={()=>setShow(!show)}><Eye/></button></div></label><div className="login-options"><label><input type="checkbox" defaultChecked/>{en?"Remember me":"Se souvenir de moi"}</label><button type="button" onClick={()=>setError(en?"Password recovery will be connected with Supabase Auth.":"La récupération sera connectée à Supabase Auth.")}>{en?"Forgot password?":"Mot de passe oublié ?"}</button></div>{error&&<div className="login-error">{error}</div>}<button className="signin" type="submit">{en?"Sign in to KCS Nexus":"Se connecter à KCS Nexus"}<ChevronRight/></button><div className="demo-credentials"><small>{en?"DEMO ACCESS":"ACCÈS DÉMO"}</small><p><span>Email</span><b>teacher.demo@kcs.cd</b></p><p><span>{en?"Password":"Mot de passe"}</span><b>KCS@Demo2026</b></p><button type="button" onClick={()=>{setEmail("teacher.demo@kcs.cd");setPassword("KCS@Demo2026");setError("")}}>{en?"Fill demo credentials":"Remplir les identifiants"}</button></div><InstallApp language={language}/><footer>{en?"Protected demonstration environment":"Environnement de démonstration protégé"} · KCS 2026</footer></form></section></main>}
type LibraryBook={title:string;author:string;subject:string;language:string;format:string;size:string,file:string,color:string,source:string};
function DigitalLibrary({note,language}:{note:(s:string)=>void;language:"en"|"fr"}){const en=language==="en";const[query,setQuery]=useState("");const[reader,setReader]=useState<LibraryBook|null>(null);const[offline,setOffline]=useState<string[]>([]);const base=process.env.NEXT_PUBLIC_BASE_PATH??"";const books:LibraryBook[]=[{title:"A First Book in Algebra",author:"Wallace C. Boyden",subject:"Algebra · Mathematics",language:"English",format:"PDF",size:"657 KB",file:"first-book-algebra.pdf",color:"algebra",source:"Project Gutenberg #13309"},{title:"The Elements of Euclid",author:"Euclid · John Casey",subject:"Geometry · Mathematics",language:"English",format:"PDF",size:"1.8 MB",file:"euclid-elements.pdf",color:"geometry",source:"Project Gutenberg #21076"},{title:"A History of Mathematics",author:"Florian Cajori",subject:"History · Mathematics",language:"English",format:"PDF",size:"2.3 MB",file:"history-of-mathematics.pdf",color:"history",source:"Project Gutenberg #31061"},{title:"Le Tour du monde en 80 jours",author:"Jules Verne",subject:"French · Literature",language:"Français",format:"TXT",size:"462 KB",file:"tour-du-monde.txt",color:"literature",source:"Project Gutenberg #46541"}];const shown=books.filter(b=>`${b.title} ${b.author} ${b.subject}`.toLowerCase().includes(query.toLowerCase()));const saveOffline=async(book:LibraryBook)=>{try{const url=`${base}/library/${book.file}`;const cache=await caches.open("kcs-library-v1");await cache.add(url);setOffline(x=>[...new Set([...x,book.file])]);note(en?`${book.title} is ready offline`:`${book.title} est disponible hors connexion`)}catch{note(en?"Offline download failed. Check your connection.":"Le téléchargement hors connexion a échoué.")}};return <section className="digital-library"><div className="library-hero"><div><small>KCS DIGITAL LIBRARY · OPEN COLLECTION</small><h1>{en?"Books that remain available":"Des livres toujours disponibles"}</h1><p>{en?"Real, legally reusable works for learning, reading, and discovery — stored directly in KCS Nexus.":"Des œuvres réelles et légalement réutilisables pour apprendre, lire et découvrir — stockées directement dans KCS Nexus."}</p></div><span><BookOpen/></span></div><div className="library-toolbar"><div><Search/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder={en?"Search title, author, or subject...":"Rechercher un titre, auteur ou sujet..."}/></div><p><b>{shown.length}</b> {en?"real books":"livres réels"} · {en?"Public domain":"Domaine public"}</p></div><div className="book-grid">{shown.map(book=><article className="book-card" key={book.file}><button className={`book-cover ${book.color}`} onClick={()=>setReader(book)}><span>KCS OPEN LIBRARY</span><b>{book.title}</b><small>{book.author}</small><em>{book.format}</em></button><div className="book-meta"><small>{book.subject}</small><h2>{book.title}</h2><p>{book.author}</p><div><span>{book.language}</span><span>{book.size}</span><span>{book.format}</span></div><footer><button onClick={()=>setReader(book)}><BookOpen/>{en?"Read":"Lire"}</button><a href={`${base}/library/${book.file}`} download><Download/>{en?"Download":"Télécharger"}</a><button className={offline.includes(book.file)?"cached":""} onClick={()=>saveOffline(book)}>{offline.includes(book.file)?<Check/>:<WifiIcon/>}{offline.includes(book.file)?(en?"Offline":"Hors ligne"):(en?"Save":"Garder")}</button></footer><label>{book.source} · {en?"Public domain in the USA; verify local law.":"Domaine public aux États-Unis ; vérifiez la législation locale."}</label></div></article>)}</div>{shown.length===0&&<div className="library-empty"><Search/><h2>{en?"No book found":"Aucun livre trouvé"}</h2><p>{en?"Try a different title, author, or subject.":"Essayez un autre titre, auteur ou sujet."}</p></div>}{reader&&<div className="book-reader"><header><div><small>{reader.subject}</small><b>{reader.title}</b><span>{reader.author} · {reader.source}</span></div><a href={`${base}/library/${reader.file}`} download><Download/>{en?"Download":"Télécharger"}</a><button onClick={()=>setReader(null)}><X/></button></header><iframe src={`${base}/library/${reader.file}`} title={reader.title}/></div>}</section>}
function WifiIcon(){return <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M12 20h.01M5 12.5a10 10 0 0 1 14 0M8.5 16a5 5 0 0 1 7 0"/></svg>}
function IntelligenceHub({note}:{note:(s:string)=>void}){const[view,setView]=useState("Vue d’ensemble");const[selected,setSelected]=useState<string|null>(null);const[scenario,setScenario]=useState(2);const students=[{name:"Grâce M.",grade:"Grade 11 A",risk:"Élevé",score:38,trend:"-14%",factors:["3 devoirs manquants","Absence répétée le lundi","Baisse en algèbre"]},{name:"Samuel K.",grade:"Grade 10 B",risk:"Modéré",score:57,trend:"-7%",factors:["2 quiz sous 50%","Retards fréquents","Progression ralentie"]},{name:"Naomi B.",grade:"Grade 11 A",risk:"Modéré",score:64,trend:"-4%",factors:["Concept du discriminant fragile","1 devoir manquant","Participation en baisse"]},{name:"David T.",grade:"Grade 12 A",risk:"À suivre",score:71,trend:"+2%",factors:["Résultats irréguliers","Bonne assiduité","Reprise récente"]}];return <section className="intel"><div className="intel-head"><div><small>KCS NEXUS · INTELLIGENCE ACADÉMIQUE</small><h1>Du signal à l’action</h1><p>Comprenez chaque alerte, vérifiez les preuves et coordonnez une intervention humaine.</p></div><div className="live"><i/> Données synchronisées · 07:24</div></div><div className="intel-tabs">{["Vue d’ensemble","Maîtrise","Interventions","Scénarios"].map(x=><button key={x} className={view===x?"active":""} onClick={()=>setView(x)}>{x}</button>)}</div>{view==="Vue d’ensemble"&&<><div className="signal-grid"><article className="signal-main"><div><span><Sparkles/></span><p><small>INSIGHT PRIORITAIRE</small><b>La maîtrise de la factorisation a diminué de 11% en Grade 11 A.</b><em>Signal fondé sur 3 évaluations, 26 élèves et 4 semaines de données.</em></p></div><button onClick={()=>setView("Maîtrise")}>Examiner les preuves <ChevronRight/></button></article><article><small>ÉLÈVES À ACCOMPAGNER</small><b>4</b><p>2 risques élevés · 2 modérés</p><span className="bad">+1 cette semaine</span></article><article><small>INTERVENTIONS ACTIVES</small><b>7</b><p>5 progressent · 2 à revoir</p><span className="good">71% efficaces</span></article></div><div className="intel-layout"><div className="risk-list"><div className="risk-title"><div><h2>Élèves nécessitant une attention</h2><p>Priorisation transparente, jamais décision automatique.</p></div><button onClick={()=>note("Rapport d’accompagnement généré")}>Générer le rapport</button></div>{students.map(s=><button key={s.name} onClick={()=>setSelected(s.name)}><span className={`risk-dot ${s.risk==="Élevé"?"high":s.risk==="Modéré"?"mid":"low"}`}/><div className="avatar">{s.name.split(" ").map(x=>x[0]).join("")}</div><p><b>{s.name}</b><small>{s.grade} · {s.factors[0]}</small></p><em>{s.trend}</em><strong>{s.risk}</strong><ChevronRight/></button>)}</div><aside className="pulse"><h2>Pulse de la classe</h2><p>Grade 11 A · 26 élèves</p><div className="pulse-ring"><span><b>76</b><small>/100</small></span></div><div className="pulse-row"><span>Engagement</span><b>82%</b></div><div className="pulse-row"><span>Maîtrise</span><b>74%</b></div><div className="pulse-row"><span>Assiduité</span><b>91%</b></div><button onClick={()=>setView("Scénarios")}><Sparkles/> Explorer un scénario</button></aside></div></>}{view==="Maîtrise"&&<div className="mastery-board"><div className="board-head"><div><h2>Carte vivante des compétences</h2><p>Grade 11 A · Mathématiques · Trimestre 1</p></div><button onClick={()=>note("Critères de maîtrise affichés")}>Voir les critères</button></div><div className="heat-head"><b>Élève</b>{["Coefficients","Factorisation","Discriminant","Graphique","Modélisation"].map(x=><span key={x}>{x}</span>)}</div>{[["Grâce M.",82,38,44,61,52],["Samuel K.",74,57,49,68,63],["Naomi B.",91,72,64,79,76],["David T.",86,78,71,82,69],["Moyenne classe",83,61,57,73,65]].map((row,i)=><div className={`heat-row ${i===4?"average":""}`} key={String(row[0])}><b>{row[0]}</b>{row.slice(1).map((v,j)=><button key={j} className={Number(v)<50?"h-low":Number(v)<70?"h-mid":"h-good"} onClick={()=>note(`${row[0]} · ${["Coefficients","Factorisation","Discriminant","Graphique","Modélisation"][j]} : ${v}%`)}>{v}%</button>)}</div>)}<div className="evidence"><Sparkles/><div><b>Lecture suggérée</b><p>La difficulté est concentrée sur la factorisation et le discriminant. Une reprise en petits groupes est recommandée avant la prochaine séquence.</p><small>Suggestion IA · à valider par l’enseignant</small></div><button onClick={()=>{setView("Interventions");note("Plan de remédiation préparé")}}>Préparer une intervention</button></div></div>}{view==="Interventions"&&<div className="interventions"><div className="intervention-head"><div><h2>Plans d’accompagnement</h2><p>Chaque action a un responsable, une échéance et un résultat observable.</p></div><button onClick={()=>note("Nouveau plan d’intervention ouvert")}><Plus/> Nouveau plan</button></div>{[["Groupe factorisation","6 élèves","M. Jonathan","28 août","En cours",72],["Suivi de Grâce M.","Individuel","M. Jonathan + Parent","30 août","Prioritaire",35],["Atelier discriminant","Grade 11 A","Département Maths","2 sept.","Planifié",10]].map(x=><article key={String(x[0])}><span><Check/></span><div><small>PLAN D’INTERVENTION</small><b>{x[0]}</b><p>{x[1]} · Responsable : {x[2]}</p></div><time>{x[3]}</time><em>{x[4]}</em><div className="mini-progress"><i style={{width:`${x[5]}%`}}/></div><button onClick={()=>note(`${x[0]} ouvert`)}><ChevronRight/></button></article>)}</div>}{view==="Scénarios"&&<div className="scenario"><div className="scenario-control"><small>SIMULATEUR PÉDAGOGIQUE</small><h2>Et si nous ajoutions du temps de remédiation ?</h2><p>Explorez une hypothèse sans modifier les données officielles. Les résultats sont des estimations, pas des promesses.</p><label><span>Sessions supplémentaires par semaine</span><b>{scenario}</b></label><input type="range" min="0" max="5" value={scenario} onChange={e=>setScenario(Number(e.target.value))}/><div className="scenario-options"><button className="active">Petits groupes</button><button onClick={()=>note("Tutorat individuel sélectionné")}>Tutorat individuel</button><button onClick={()=>note("Pratique autonome sélectionnée")}>Pratique autonome</button></div></div><div className="projection"><small>PROJECTION SUR 4 SEMAINES</small><div><span>Maîtrise actuelle<b>61%</b></span><ChevronRight/><span>Maîtrise estimée<b>{61+scenario*4}%</b></span></div><div className="projection-bars"><i style={{height:"61%"}}/><i style={{height:`${61+scenario*4}%`}}/></div><p><Sparkles/> Estimation basée sur les progrès observés lors d’interventions comparables.</p><button onClick={()=>{setView("Interventions");note("Scénario converti en plan brouillon")}}>Transformer en plan d’action</button></div></div>}{selected&&<div className="student-drawer"><button className="drawer-bg" onClick={()=>setSelected(null)}/><aside><header><div><small>ANALYSE EXPLICABLE</small><h2>{selected}</h2><p>{students.find(x=>x.name===selected)?.grade}</p></div><button onClick={()=>setSelected(null)}><X/></button></header><div className="student-score"><span>{students.find(x=>x.name===selected)?.score}</span><div><b>Niveau d’attention</b><p>{students.find(x=>x.name===selected)?.risk}</p></div></div><h3>Pourquoi ce signal ?</h3>{students.find(x=>x.name===selected)?.factors.map((x,i)=><div className="factor" key={x}><span>0{i+1}</span><p><b>{x}</b><small>Source vérifiable dans le dossier académique</small></p><ChevronRight/></div>)}<div className="human-note"><b>Décision humaine requise</b><p>Ces signaux servent à orienter l’attention. Ils ne constituent ni un diagnostic ni une décision académique.</p></div><button className="action-plan" onClick={()=>{setSelected(null);setView("Interventions");note("Plan d’accompagnement créé en brouillon")}}>Créer un plan d’accompagnement</button></aside></div>}</section>}
function LessonStudio({note}:{note:(s:string)=>void}){const[tab,setTab]=useState("Séquence");const[present,setPresent]=useState(false);const[slide,setSlide]=useState(0);const[steps,setSteps]=useState([{type:"Introduction",title:"Situation-problème",detail:"Pourquoi une parabole apparaît-elle dans la vie réelle ?",icon:"01"},{type:"Présentation",title:"Comprendre la forme ax² + bx + c",detail:"Support interactif · 8 diapositives",icon:"02"},{type:"Vidéo",title:"Visualiser les racines d’une équation",detail:"Vidéo KCS · 04:32",icon:"03"},{type:"Pratique guidée",title:"Résoudre par factorisation",detail:"6 exercices progressifs",icon:"04"},{type:"Évaluation",title:"Vérification formative",detail:"Quiz rapide · 5 questions",icon:"05"}]);
const addStep=()=>{const n=steps.length+1;setSteps([...steps,{type:"Activité",title:`Nouvelle activité ${n}`,detail:"À configurer",icon:String(n).padStart(2,"0")}]);note("Nouvelle étape ajoutée")};const current=steps[slide]??steps[0];return <section className="studio"><div className="studio-top"><div><small>STUDIO DE LEÇON · MATHÉMATIQUES</small><h1>Équations quadratiques</h1><p>Grade 11 A · 50 minutes · Mercredi 26 août</p></div><div><button onClick={()=>note("Brouillon enregistré")}><Save/> Enregistrer</button><button className="present-btn" onClick={()=>{setSlide(0);setPresent(true)}}><Presentation/> Présenter</button></div></div><div className="studio-tabs">{["Aperçu","Séquence","Différenciation","Maîtrise"].map(x=><button className={tab===x?"active":""} key={x} onClick={()=>setTab(x)}>{x}</button>)}</div>{tab==="Séquence"&&<div className="studio-grid"><div className="sequence"><div className="sequence-head"><div><h2>Séquence pédagogique</h2><p>Construisez le déroulé utilisé pendant le cours.</p></div><button onClick={addStep}><Plus/> Ajouter une étape</button></div>{steps.map((x,i)=><article key={`${x.title}-${i}`}><GripVertical/><span>{x.icon}</span><div><small>{x.type}</small><b>{x.title}</b><p>{x.detail}</p></div><button onClick={()=>note(`${x.title} ouvert`)}><Eye/></button></article>)}</div><aside className="lesson-side"><div className="lesson-score"><span><Sparkles/></span><small>QUALITÉ PÉDAGOGIQUE</small><b>92%</b><p>Objectifs, activités et évaluation sont bien alignés.</p></div><div className="lesson-info"><h3>Objectifs d’apprentissage</h3><label><Check/> Identifier les coefficients a, b et c</label><label><Check/> Résoudre par factorisation</label><label><Check/> Interpréter les racines graphiquement</label><button onClick={()=>note("Objectifs modifiables ouverts")}>Modifier les objectifs</button></div><button className="ai-diff" onClick={()=>{setTab("Différenciation");note("Versions différenciées générées")}}><WandSparkles/><span><b>Différencier avec l’IA</b><small>Simple · Standard · Avancé</small></span><ChevronRight/></button></aside></div>}{tab==="Aperçu"&&<div className="overview-grid"><article><span><BookOpen/></span><h2>Intention pédagogique</h2><p>Amener les élèves à relier les représentations algébrique et graphique d’une fonction quadratique, puis à choisir une stratégie de résolution adaptée.</p></article><article><span><Clock3/></span><h2>Déroulement</h2><p>Accroche 5 min · Explication 12 min · Pratique guidée 15 min · Travail autonome 12 min · Vérification 6 min.</p></article><article><span><Library/></span><h2>Ressources liées</h2><p>Présentation interactive, vidéo KCS, fiche d’exercices et quiz formatif. Disponibles hors connexion après synchronisation.</p></article></div>}{tab==="Différenciation"&&<div className="levels">{[["Essentiel","Pour les élèves ayant besoin d’un guidage renforcé","Exemples résolus · indices visuels · 4 exercices"],["Standard","Parcours prévu pour la majorité de la classe","Explication · pratique guidée · 6 exercices"],["Approfondissement","Pour les élèves prêts à aller plus loin","Problème ouvert · justification · défi graphique"]].map((x,i)=><article key={x[0]}><span>0{i+1}</span><div><h2>{x[0]}</h2><p>{x[1]}</p><small>{x[2]}</small></div><button onClick={()=>note(`Version ${x[0]} ouverte`)}>Ouvrir <ChevronRight/></button></article>)}</div>}{tab==="Maîtrise"&&<div className="mastery"><div><h2>Carte de maîtrise</h2><p>Données fictives de démonstration · critères transparents</p></div>{[["Identifier les coefficients",88,"Maîtrisé"],["Factoriser un trinôme",74,"En progression"],["Interpréter le discriminant",61,"À renforcer"],["Relier racines et graphique",79,"En progression"]].map(x=><article key={x[0]}><b>{x[0]}</b><div><i style={{width:`${x[1]}%`}}/></div><strong>{x[1]}%</strong><em>{x[2]}</em></article>)}</div>}{present&&<div className="present-mode"><header><div><Image src={`${process.env.NEXT_PUBLIC_BASE_PATH??""}/kcs.jpg`} width={34} height={34} alt="KCS"/><span>KCS NEXUS · MODE PRÉSENTATION</span></div><button onClick={()=>setPresent(false)}><X/> Quitter</button></header><main><small>{current.type} · {slide+1}/{steps.length}</small><h1>{current.title}</h1><p>{current.detail}</p>{slide===0&&<div className="big-question">Où voyez-vous des courbes en forme de parabole autour de vous ?</div>}{slide===1&&<div className="formula">f(x) = ax² + bx + c</div>}<div className="present-nav"><button disabled={slide===0} onClick={()=>setSlide(Math.max(0,slide-1))}>Précédent</button><div>{steps.map((_,i)=><i key={i} className={i===slide?"active":""}/>)}</div><button disabled={slide===steps.length-1} onClick={()=>setSlide(Math.min(steps.length-1,slide+1))}>Suivant <ChevronRight/></button></div></main></div>}</section>}
function ModulePage({name,note,language}:{name:string;note:(s:string)=>void;language:"en"|"fr"}){const[prompt,setPrompt]=useState("");if(name==="Leçons")return <LessonStudio note={note}/>;if(name==="Nexus Intelligence")return <IntelligenceHub note={note}/>;if(name==="Ressources")return <DigitalLibrary note={note} language={language}/>;if(name==="Assistant IA")return <section className="module"><div className="module-head"><div><small>KCS NEXUS INTELLIGENCE</small><h1>Assistant IA enseignant</h1><p>Préparez une leçon, créez un exercice ou analysez une progression avec l’aide de KCS Nexus.</p></div></div><div className="ai-workspace"><span><Sparkles/></span><h2>Comment puis-je vous aider aujourd’hui ?</h2><p>Les contenus générés restent des propositions à vérifier avant publication.</p><div><input value={prompt} onChange={e=>setPrompt(e.target.value)} onKeyDown={e=>{if(e.key==="Enter"&&prompt.trim()){note("Demande envoyée à l’assistant IA");setPrompt("")}}} placeholder="Ex. Crée une leçon de Grade 11 sur les équations quadratiques..."/><button onClick={()=>{if(prompt.trim()){note("Demande envoyée à l’assistant IA");setPrompt("")}else note("Saisissez d’abord votre demande")}}><Sparkles/> Générer</button></div><div className="suggestions">{["Créer un plan de leçon","Générer un quiz","Différencier une activité","Analyser les résultats"].map(x=><button key={x} onClick={()=>setPrompt(x)}>{x}</button>)}</div></div></section>;
const m=modules[name]??modules["Mes classes"];return <section className="module"><div className="module-head"><div><small>{m.eyebrow}</small><h1>{m.title}</h1><p>{m.description}</p></div><button className="primary" onClick={()=>note(`${m.action} — formulaire ouvert`)}><Plus/><span>{m.action}</span></button></div><div className="module-stats">{m.stats.map(x=><article key={x[0]}><small>{x[0]}</small><b>{x[1]}</b><span>{x[2]}</span></article>)}</div><div className="module-tools"><div><Search/><input placeholder={`Rechercher dans ${m.title.toLowerCase()}...`}/></div><button onClick={()=>note("Filtres ouverts")}>Tous les filtres <ChevronDown/></button></div><div className="data-panel"><table><thead><tr>{m.columns.map(x=><th key={x}>{x}</th>)}<th></th></tr></thead><tbody>{m.rows.map((row,i)=><tr key={i} onClick={()=>note(`${row[0]} ouvert`)}>{row.map((cell,j)=><td key={j} data-label={m.columns[j]}>{j===0?<b>{cell}</b>:j===row.length-1?<em>{cell}</em>:cell}</td>)}<td><ChevronRight/></td></tr>)}</tbody></table></div></section>}
function Stat({icon,k,v,d,c}:{icon:React.ReactNode;k:string;v:string;d:string;c:string}){return <article className="stat"><span className={c}>{icon}</span><p><small>{k}</small><b>{v}</b><em>{d}</em></p><ChevronRight/></article>}
function Title({t,a,go}:{t:string;a?:string;go?:()=>void}){return <div className="title"><h3>{t}</h3>{a&&<button onClick={go}>{a}<ChevronRight/></button>}</div>}
function Quick({i,t,c,go}:{i:React.ReactNode;t:string;c:string;go:()=>void}){return <button onClick={go}><span className={c}>{i}</span><b>{t}</b><ChevronRight/></button>}